SELECT b.mktcode,b.tgtcode,b.bizdate FROM `newzl`.`hsj_stock_hq_basic` AS b WHERE b.bizdate='2026-04-14' AND b.volume>100 AND ((b.mktcode=1 AND ((b.tgtcode>='600000' AND b.tgtcode<='600999') OR (b.tgtcode>='601000' AND b.tgtcode<='601999') OR (b.tgtcode>='603000' AND b.tgtcode<='603999') OR (b.tgtcode>='605000' AND b.tgtcode<='605999'))) OR (b.mktcode=0 AND ((b.tgtcode>='000000' AND b.tgtcode<='000999') OR (b.tgtcode>='001000' AND b.tgtcode<='001999') OR (b.tgtcode>='002000' AND b.tgtcode<='002999') OR (b.tgtcode>='003000' AND b.tgtcode<='003999'))));
